SELECT
  count(*) totcnt
FROM
  ttokssaemdb.voca voca


    AND (
      voca.word LIKE #{likeQuery}
      OR
      voca.explain LIKE #{likeQuery}
      OR
      voca.answer LIKE #{likeQuery}
    )

SELECT R1.* FROM( SELECT voca.id, voca.vocalevel, (SELECT codename FROM cmm_code WHERE code = voca.vocalevel AND codetype = 'VOCALEVEL') vocalevel_name, voca.vocano, voca.word, voca.explain, voca.answer FROM ttokssaemdb.voca voca
AND ( voca.word LIKE #{likeQuery} OR voca.explain LIKE #{likeQuery} OR voca.answer LIKE #{likeQuery} )
voca.id voca.vocalevel voca.vocalevel voca.vocano voca.word DESC ASC DESC
) R1
LIMIT ${length} OFFSET ${start}
